/**
 * Probe diary entry photos.
 *
 * Checks the whole shape of the feature, not just the happy path: that a photo
 * attaches, that the presigned URL actually resolves to image bytes, that the raw
 * storage key never leaves the server, that replacing a photo works, and that
 * deleting the entry does not leave the object behind.
 *
 * The image is generated by YouCam's own text-to-image endpoint, so no real
 * person's photograph is involved.
 */

import { readFileSync, writeFileSync } from 'node:fs';

const BASE = readFileSync('deployed-url.txt', 'utf8').trim().replace(/\/+$/, '');
const CODE = readFileSync('access-code.txt', 'utf8').trim();
const IMAGE_URL = process.argv[2];

const out = [];
const log = (l) => {
  out.push(l);
  console.log(l);
};

const image = Buffer.from(await (await fetch(IMAGE_URL)).arrayBuffer());
log(`source image: ${(image.length / 1024).toFixed(0)} KB`);

const token = (
  await (
    await fetch(`${BASE}/session`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: `photo+${Date.now()}@example.com`, code: CODE }),
    })
  ).json()
).token;
const auth = { Authorization: `Bearer ${token}` };
const json = { ...auth, 'Content-Type': 'application/json' };

// ------------------------------------------------------------------ create

const created = await (
  await fetch(`${BASE}/v1/notes`, {
    method: 'POST',
    headers: json,
    body: JSON.stringify({ body: 'Started the new serum tonight.', tags: ['new_product', 'calm'] }),
  })
).json();
const id = created.note.id;
log(`note created: ${id}  photoUrl=${created.note.photoUrl}  imageKey leaked=${'imageKey' in created.note}`);

// ------------------------------------------------------------------- attach

async function attach(label) {
  const form = new FormData();
  form.set('image', new Blob([image], { type: 'image/jpeg' }), 'entry.jpg');
  const res = await fetch(`${BASE}/v1/notes/${id}/photo`, {
    method: 'POST',
    headers: auth,
    body: form,
  });
  const body = await res.json();
  log(`${label}: ${res.status}  photoUrl=${body.note?.photoUrl ? 'present' : 'MISSING'}  imageKey leaked=${'imageKey' in (body.note ?? {})}`);
  return body.note?.photoUrl ?? null;
}

const url = await attach('attach photo');

// The presigned URL is the only way a client can see the image, so a URL that does
// not resolve is the same as no feature at all.
if (url) {
  const fetched = await fetch(url);
  log(`presigned fetch: ${fetched.status} ${fetched.headers.get('content-type')} ${fetched.headers.get('content-length')} bytes`);
}

// Replacing must not leave the previous object orphaned. Same key, so it overwrites.
await attach('replace photo');

// -------------------------------------------------------- listed and windowed

const listed = await (await fetch(`${BASE}/v1/notes`, { headers: auth })).json();
log(`list: ${listed.notes.length} note(s), with photo: ${listed.notes.filter((n) => n.photoUrl).length}`);

// -------------------------------------------------------------- non-image

const bad = new FormData();
bad.set('image', new Blob([Buffer.from('not an image at all')], { type: 'image/jpeg' }), 'x.jpg');
const badRes = await fetch(`${BASE}/v1/notes/${id}/photo`, {
  method: 'POST',
  headers: auth,
  body: bad,
});
log(`mislabelled file: ${badRes.status}  ${(await badRes.text()).slice(0, 160).replace(/\s+/g, ' ')}`);

// ------------------------------------------------------------------ delete

const gone = await fetch(`${BASE}/v1/notes/${id}`, { method: 'DELETE', headers: auth });
log(`delete note: ${gone.status} ${await gone.text()}`);

// The object should now be unreachable. The presigned URL may still be within its
// TTL, so this checks the API's view rather than S3's.
const after = await (await fetch(`${BASE}/v1/notes`, { headers: auth })).json();
log(`notes remaining: ${after.notes.length}`);

writeFileSync('probe-note-photo.txt', out.join('\n'));
